export function lookupFootwearStyleMetadata(key?: string): FootwearStyleMetadata | undefined {
  if (!key) return undefined;
  const clean = key.trim().toUpperCase();
  if (FOOTWEAR_BARCODE_CATALOG[clean]) return FOOTWEAR_BARCODE_CATALOG[clean];
  if (FOOTWEAR_STYLE_CATALOG[clean]) return FOOTWEAR_STYLE_CATALOG[clean];

  // Try style prefix extraction e.g. SND-10-J-BLACK-36 -> SND-10-J or SND-10
  const parts = clean.split('-');
  if (parts.length >= 2) {
    const twoPart = `${parts[0]}-${parts[1]}`;
    if (FOOTWEAR_STYLE_CATALOG[twoPart]) return FOOTWEAR_STYLE_CATALOG[twoPart];
    if (parts.length >= 3) {
      const threePart = `${parts[0]}-${parts[1]}-${parts[2]}`;
      if (FOOTWEAR_STYLE_CATALOG[threePart]) return FOOTWEAR_STYLE_CATALOG[threePart];
    }
  }

  // Substring search fallback
  for (const [styleName, meta] of Object.entries(FOOTWEAR_STYLE_CATALOG)) {
    if (clean.includes(styleName) || styleName.includes(clean)) {
      return meta;
    }
  }
  return undefined;
}
